(function(){const A=[{"id":"sp6-pokrov-voln","n":"Покров Волн","l":1,"sc":"Ограждение","t":"1 действие","r":"На себя","c":"ВСМ","m":"Морская ракушка.","d":"1 час","conc":false,"rit":false,"dmg":"5 дробящий","cl":["Жрец","Паладин","Изобретатель"],"ds":"Вы получаете 5 временных хитов. Пока они есть, существо, попавшее по вам рукопашной атакой, получает 5 урона (дробящий); у вас сопротивление урону «дробящий». На больших уровнях: +5 временных хитов и +5 ответного урона за каждый уровень ячейки выше 1-го.","save":"","atk":false,"mech":"Покров","theme":"Волн","orig":true,"pack":"spells6.js"},{"id":"sp6-kolco-vetra","n":"Кольцо Ветра","l":6,"sc":"Воплощение","t":"1 действие","r":"45 м","c":"ВСМ","m":"Перо.","d":"Концентрация, до 10 минут","conc":true,"rit":false,"dmg":"6к8 звук","cl":["Чародей","Друид"],"ds":"Кольцо радиусом до 18 м. Существо внутри не может пересечь кольцо без спасброска (Сила): при провале оно получает 6к8 урона (звук), не проходит и отталкивается на 4,5 м в выбранном вами направлении; при успехе — половина урона и проходит. Вы выбираете существ, которых кольцо пропускает. На больших уровнях: +1к8 за каждый уровень ячейки выше 6-го.","save":"Сила","atk":false,"mech":"Кольцо","theme":"Ветра","orig":true,"pack":"spells6.js"},{"id":"sp6-ubezhische-kamnya","n":"Убежище Камня","l":3,"sc":"Ограждение","t":"1 минута","r":"На себя (полусфера 3 м)","c":"ВСМ","m":"Кусочек гранита.","d":"8 часов","conc":false,"rit":true,"dmg":"—","cl":["Изобретатель","Друид","Паладин"],"ds":"Над вами возникает неподвижное убежище для 9 Средних существ: каменная хижина, вырастающая из земли и уходящая обратно. Существа и предметы внутри при сотворении могут свободно выходить и входить; прочие — нет. Магия не проходит сквозь стены.","save":"","atk":false,"mech":"Убежище","theme":"Камня","orig":true,"pack":"spells6.js"},{"id":"sp6-chute-duhov","n":"Чутьё Духов","l":1,"sc":"Прорицание","t":"1 действие","r":"На себя (9 м)","c":"ВС","m":"","d":"Концентрация, до 10 минут","conc":true,"rit":true,"dmg":"—","cl":["Бард","Колдун","Жрец"],"ds":"Вы чувствуете призраков, одержимых существ и духов места в пределах 9 м и знаете их направление. Чутьё проходит сквозь большинство преград, но блокируется 30 см камня, 2,5 см металла или тонким листом свинца.","save":"","atk":false,"mech":"Чутьё","theme":"Духов","orig":true,"pack":"spells6.js"},{"id":"sp6-katastrofa-mirazhey","n":"Катастрофа Миражей","l":7,"sc":"Иллюзия","t":"1 действие","r":"300 м","c":"ВСМ","m":"Кусочек стекла.","d":"Мгновенная","conc":false,"rit":false,"dmg":"12к6 психический","cl":["Бард","Колдун"],"ds":"Сфера радиусом 12 м: существа совершают спасбросок (Интеллект) — 12к6 урона (психический) при провале (и цель видит ложные образы: помеха на следующий бросок атаки до конца её следующего хода), половина при успехе. Местность становится труднопроходимой на 1 час. На больших уровнях: +1к6 за каждый уровень ячейки выше 7-го.","save":"Интеллект","atk":false,"mech":"Катастрофа","theme":"Миражей","orig":true,"pack":"spells6.js"},{"id":"sp6-opros-sveta","n":"Опрос Света","l":3,"sc":"Прорицание","t":"10 минут","r":"Касание","c":"ВСМ","m":"Святой символ.","d":"10 минут","conc":false,"rit":true,"dmg":"—","cl":["Паладин","Жрец","Бард"],"ds":"Вы обращаетесь к стихии: вопрошаете святое место или символ (божество отвечает видением). Вы можете задать до трёх вопросов и получаете короткие правдивые ответы, ограниченные тем, что могла «видеть» стихия.","save":"","atk":false,"mech":"Опрос","theme":"Света","orig":true,"pack":"spells6.js"},{"id":"sp6-shag-shipov","n":"Шаг Шипов","l":1,"sc":"Вызов","t":"1 бонусное действие","r":"На себя","c":"В","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"1к6 колющий","cl":["Следопыт","Друид","Бард"],"ds":"Вы телепортируетесь на 9 м в видимое свободное место. Каждое существо в 1,5 м от точки отправления совершает спасбросок (Сила) или получает 1к6 урона (колющий). На больших уровнях: +3 м дистанции и +1к6 за каждый уровень ячейки выше 1-го.","save":"Сила","atk":false,"mech":"Шаг","theme":"Шипов","orig":true,"pack":"spells6.js"},{"id":"sp6-vlast-run","n":"Власть Рун","l":8,"sc":"Ограждение","t":"1 действие","r":"На себя (1,5 км)","c":"ВС","m":"","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"6к10 силовое поле","cl":["Жрец","Волшебник"],"ds":"Вы повелеваете стихией (рун) в радиусе 1,5 км: создаёте, гасите, перемещаете и формируете её проявления. Действием вы обрушиваете её на существо в 36 м: спасбросок (Интеллект), 6к10 урона (силовое поле) при провале и цель получает светящуюся руну: следующая атака по ней до конца вашего следующего хода получает +1к4 к броску, половина при успехе.","save":"Интеллект","atk":false,"mech":"Власть","theme":"Рун","orig":true,"pack":"spells6.js"},{"id":"sp6-burya-vremeni","n":"Буря Времени","l":4,"sc":"Преобразование","t":"1 действие","r":"90 м","c":"ВСМ","m":"Песчинка из песочных часов.","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"3к6 силовое поле","cl":["Изобретатель","Бард","Чародей"],"ds":"Буря (времени) в цилиндре радиусом 6 м и высотой 12 м: местность труднопроходимая. Существо, начинающее ход в буре или впервые входящее в неё за ход, совершает спасбросок (Мудрость): 3к6 урона (силовое поле) при провале, половина при успехе. На больших уровнях: +1к6 за каждый уровень ячейки выше 4-го.","save":"Мудрость","atk":false,"mech":"Буря","theme":"Времени","orig":true,"pack":"spells6.js"},{"id":"sp6-sfera-teni","n":"Сфера Тени","l":2,"sc":"Иллюзия","t":"1 действие","r":"18 м","c":"ВСМ","m":"Клочок чёрной ткани.","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"2к6 некротика","cl":["Колдун","Волшебник","Чародей"],"ds":"Сфера (тени) диаметром 1,5 м появляется в пределах дистанции. Существо, оканчивающее ход в 1,5 м от неё, совершает спасбросок (Мудрость): 2к6 урона (некротика) при провале, половина при успехе. Бонусным действием сфера перемещается на 9 м; если она врезается в существо, оно совершает спасбросок, и сфера останавливается. На больших уровнях: +1к6 за каждый уровень ячейки выше 2-го.","save":"Мудрость","atk":false,"mech":"Сфера","theme":"Тени","orig":true,"pack":"spells6.js"},{"id":"sp6-apokalipsis-krovi","n":"Апокалипсис Крови","l":9,"sc":"Некромантия","t":"1 действие","r":"1,5 км","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"14к6+14к6 некротика","cl":["Чародей","Жрец"],"ds":"Вы выбираете до четырёх точек; от каждой расходится сфера радиусом 12 м. Существо в одной или нескольких сферах совершает один спасбросок (Телосложение): 14к6 урона (некротика) плюс 14к6 силовым полем при провале (и цель не может восстанавливать хиты до конца своего следующего хода), половина при успехе. Предметы и строения в области получают двойной урон.","save":"Телосложение","atk":false,"mech":"Апокалипсис","theme":"Крови","orig":true,"pack":"spells6.js"},{"id":"sp6-vrata-molniy","n":"Врата Молний","l":4,"sc":"Ограждение","t":"1 действие","r":"18 м","c":"ВСМ","m":"Кусочек янтаря.","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"4к10 электричество","cl":["Чародей","Друид","Паладин"],"ds":"Существо совершает спасбросок Харизмы или проваливается в карман-измерение (молний). Там оно недееспособно. Когда заклинание оканчивается, цель возвращается и получает 4к10 урона (электричество). Если концентрация продержалась полную минуту, урон удваивается. На больших уровнях: +1 цель за каждый уровень ячейки выше 4-го.","save":"Харизма","atk":false,"mech":"Врата","theme":"Молний","orig":true,"pack":"spells6.js"},{"id":"sp6-zavesa-groma","n":"Завеса Грома","l":2,"sc":"Воплощение","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Концентрация, до 10 минут","conc":true,"rit":false,"dmg":"—","cl":["Чародей","Бард","Жрец"],"ds":"Куб с ребром 6 м заполняется завесой (грома): местность труднопроходимая и слабо заслонённая. Существо, впервые за ход входящее туда, совершает спасбросок (Телосложение) — при провале оно отбрасывается на 3 м от источника и не может совершать реакции до начала своего хода. На больших уровнях: +3 м к ребру куба за каждый уровень ячейки выше 2-го.","save":"Телосложение","atk":false,"mech":"Завеса","theme":"Грома","orig":true,"pack":"spells6.js"},{"id":"sp6-kasanie-ineya","n":"Касание Инея","l":0,"sc":"Воплощение","t":"1 действие","r":"Касание","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"1к8 холод","cl":["Чародей","Друид","Волшебник"],"ds":"Рукопашная атака заклинанием: при попадании 1к8 урона (холод), и цель покрывается коркой льда: скорость уменьшается на 3 м до конца её следующего хода. Урон увеличивается на одну кость на 5, 11 и 17 уровнях.","save":"","atk":true,"mech":"Касание","theme":"Инея","orig":true,"pack":"spells6.js"},{"id":"sp6-tropa-plameni","n":"Тропа Пламени","l":4,"sc":"Преобразование","t":"10 минут","r":"Касание","c":"ВСМ","m":"Щепоть серы.","d":"8 часов","conc":false,"rit":true,"dmg":"—","cl":["Изобретатель","Колдун","Следопыт"],"ds":"До 8 согласных существ отправляются в путь сквозь пламя: из одного костра или очага в другой. На время действия скорость путешествия группы удваивается, а случайные столкновения в пути случаются вдвое реже.","save":"","atk":false,"mech":"Тропа","theme":"Пламени","orig":true,"pack":"spells6.js"},{"id":"sp6-oruzhie-kostey","n":"Оружие Костей","l":2,"sc":"Преобразование","t":"1 бонусное действие","r":"Касание","c":"ВС","m":"","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"1к6 колющий","cl":["Паладин","Следопыт","Изобретатель"],"ds":"Немагическое оружие становится магическим с бонусом +1 к атаке и наносит дополнительно 1к6 урона (колющий). Один раз в ход при попадании владелец может заставить цель совершить спасбросок (Телосложение): при провале она становится хрупкой: следующий дробящий урон по ней до конца её следующего хода увеличивается на 1к6. Ячейкой 4–5 уровня бонус +2, 6+ уровня — +3.","save":"","atk":false,"mech":"Оружие","theme":"Костей","orig":true,"pack":"spells6.js"},{"id":"sp6-vspyshka-pustoty","n":"Вспышка Пустоты","l":0,"sc":"Вызов","t":"1 действие","r":"На себя (1,5 м)","c":"С","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"1к6 силовое поле","cl":["Чародей","Колдун","Волшебник"],"ds":"Каждое существо по вашему выбору в пределах 1,5 м совершает спасбросок (Харизма), получая 1к6 урона (силовое поле) при провале. Не требует видеть цели. Урон увеличивается на одну кость на 5, 11 и 17 уровнях.","save":"Харизма","atk":false,"mech":"Вспышка","theme":"Пустоты","orig":true,"pack":"spells6.js"},{"id":"sp6-proklyatie-zvezd","n":"Проклятие Звёзд","l":4,"sc":"Некромантия","t":"1 действие","r":"Касание","c":"ВС","m":"","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"2к6 излучение","cl":["Бард","Жрец","Волшебник"],"ds":"Цель совершает спасбросок Мудрости. При провале ваши атаки и заклинания наносят ей дополнительно 2к6 урона (излучение), а в начале каждого её хода она бросает к4: на 1 она очерчивается звёздным светом: атаки по ней совершаются с преимуществом до конца её следующего хода. «Снятие проклятия» оканчивает эффект. Ячейкой 5 уровня — 8 часов без концентрации, 7+ уровня — 24 часа.","save":"Мудрость","atk":false,"mech":"Проклятие","theme":"Звёзд","orig":true,"pack":"spells6.js"},{"id":"sp6-slepok-razuma","n":"Слепок Разума","l":2,"sc":"Преобразование","t":"1 минута","r":"Касание","c":"ВСМ","m":"Кусочек мозгового коралла.","d":"8 часов","conc":false,"rit":false,"dmg":"—","cl":["Бард","Колдун","Волшебник"],"ds":"Вы создаёте немагический предмет из отвердевшей мысли — предмет повинуется простым мысленным командам размером до куба 1,5 м: инструмент, мост, лестницу, ящик или простое оружие. Предмет имеет КД 15 и 30 хитов; через 8 часов он рассыпается. Ячейкой 4+ уровня предмет держится 24 часа, 6+ уровня — постоянно.","save":"","atk":false,"mech":"Слепок","theme":"Разума","orig":true,"pack":"spells6.js"},{"id":"sp6-maloe-chudo-yada","n":"Малое Чудо Яда","l":0,"sc":"Преобразование","t":"1 действие","r":"9 м","c":"В","m":"","d":"До 1 часа","conc":false,"rit":false,"dmg":"—","cl":["Следопыт","Колдун","Изобретатель"],"ds":"Вы творите мелкое чудо: определить, отравлена ли пища или питьё, или придать жидкости горький вкус. Одновременно активны не более трёх эффектов; вы можете окончить любой действием.","save":"","atk":false,"mech":"Малое Чудо","theme":"Яда","orig":true,"pack":"spells6.js"},{"id":"sp6-legion-voln","n":"Легион Волн","l":5,"sc":"Вызов","t":"1 действие","r":"27 м","c":"ВСМ","m":"Морская ракушка.","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"2к6 дробящий","cl":["Жрец","Друид","Следопыт"],"ds":"Появляются четыре духа (волн): Маленькие, КД 15, хиты 20, скорость 12 м, иммунитет к урону «дробящий». Каждый атакует заклинанием 1,5 м на 2к6 урона (дробящий). Действуют в вашу инициативу по вашим мысленным командам (без действия). На больших уровнях: +1 дух за каждый уровень ячейки выше 5-го.","save":"","atk":true,"mech":"Легион","theme":"Волн","orig":true,"pack":"spells6.js"},{"id":"sp6-pechat-vetra","n":"Печать Ветра","l":2,"sc":"Ограждение","t":"10 минут","r":"Касание","c":"ВСМ","m":"Перо.","d":"8 часов","conc":false,"rit":true,"dmg":"3к6 звук","cl":["Паладин","Изобретатель","Волшебник"],"ds":"Вы чертите печать на поверхности или проходе (до 6 м). Когда существо, не названное вами, пересекает её, вы мысленно пробуждаетесь/узнаёте об этом (если вы в пределах 1,5 км), а нарушитель совершает спасбросок (Сила): 3к6 урона (звук) при провале, половина при успехе. На больших уровнях: +1к6 за каждый уровень ячейки выше 2-го.","save":"Сила","atk":false,"mech":"Печать","theme":"Ветра","orig":true,"pack":"spells6.js"},{"id":"sp6-kope-kamnya","n":"Копьё Камня","l":1,"sc":"Преобразование","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"2к10 дробящий","cl":["Изобретатель","Друид","Чародей"],"ds":"Дальнобойная атака заклинанием: при попадании 2к10 урона (дробящий). При критическом попадании копьё пробивает цель и поражает второе существо в 3 м позади неё (обычный бросок атаки). На больших уровнях: +1к10 за каждый уровень ячейки выше 1-го.","save":"","atk":true,"mech":"Копьё","theme":"Камня","orig":true,"pack":"spells6.js"},{"id":"sp6-dvoynik-duhov","n":"Двойник Духов","l":5,"sc":"Иллюзия","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"4к6 психический","cl":["Бард","Колдун","Жрец"],"ds":"Вы создаёте двойника из ткани из эктоплазмы, холодной и мягкой. Он двигается по вашей воле (бонусное действие, 9 м), вы видите и слышите его органами чувств, и ваши заклинания могут исходить от него. Двойник имеет КД 14 и 1 хит; при уничтожении взрывается: 4к6 урона (психический) в 3 м.","save":"","atk":false,"mech":"Двойник","theme":"Духов","orig":true,"pack":"spells6.js"},{"id":"sp6-potok-mirazhey","n":"Поток Миражей","l":3,"sc":"Иллюзия","t":"1 действие","r":"На себя (линия 30 м)","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"7к6 психический","cl":["Бард","Колдун","Чародей"],"ds":"Линия длиной 30 м и шириной 1,5 м. Существа на линии совершают спасбросок (Интеллект): 7к6 урона (психический) при провале, половина при успехе. Поток игнорирует укрытие на половину и на три четверти. На больших уровнях: +1к6 за каждый уровень ячейки выше 3-го.","save":"Интеллект","atk":false,"mech":"Поток","theme":"Миражей","orig":true,"pack":"spells6.js"},{"id":"sp6-uzy-sveta","n":"Узы Света","l":1,"sc":"Очарование","t":"1 действие","r":"18 м","c":"ВСМ","m":"Святой символ.","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"1к4 излучение","cl":["Паладин","Жрец","Следопыт"],"ds":"Узы (света) охватывают существо: спасбросок (Телосложение) или оно опутано. В конце каждого своего хода цель повторяет спасбросок, оканчивая эффект при успехе. Пока цель опутана, она получает 1к4 урона (излучение) в начале каждого своего хода. На больших уровнях: +1 цель за каждый уровень ячейки выше 1-го.","save":"Телосложение","atk":false,"mech":"Узы","theme":"Света","orig":true,"pack":"spells6.js"},{"id":"sp6-raspad-shipov","n":"Распад Шипов","l":6,"sc":"Преобразование","t":"1 действие","r":"18 м","c":"ВСМ","m":"Шип розы.","d":"Мгновенная","conc":false,"rit":false,"dmg":"10к10 колющий","cl":["Чародей","Друид"],"ds":"Существо совершает спасбросок Телосложения: 10к10 урона (колющий) при провале, половина при успехе. Существо, у которого хиты опустились до 0, обращается в стихию и может быть возвращено только «Истинным воскрешением» или «Желанием». На больших уровнях: +1к10 за каждый уровень ячейки выше 6-го.","save":"Телосложение","atk":false,"mech":"Распад","theme":"Шипов","orig":true,"pack":"spells6.js"},{"id":"sp6-duh-run","n":"Дух Рун","l":3,"sc":"Вызов","t":"1 действие","r":"27 м","c":"ВСМ","m":"Резец и кусочек кости.","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"1к8+6 силовое поле","cl":["Жрец","Волшебник","Следопыт"],"ds":"Вы призываете духа (рун) Среднего размера: КД 13 + уровень заклинания, хиты 30 + 10 за уровень выше 3-го, скорость 12 м. Мультиатака: число атак, равное половине уровня заклинания; атака заклинанием +ваш бонус, 1к8 + 3 + уровень урона (силовое поле). Иммунитет к урону «силовое поле». Действует сразу после вас. На больших уровнях: +10 хитов и +1 КД за каждый уровень ячейки выше 3-го.","save":"","atk":true,"mech":"Дух","theme":"Рун","orig":true,"pack":"spells6.js"},{"id":"sp6-kleymo-vremeni","n":"Клеймо Времени","l":1,"sc":"Преобразование","t":"1 бонусное действие","r":"На себя","c":"В","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"2к6 силовое поле","cl":["Изобретатель","Следопыт","Паладин"],"ds":"Следующее ваше попадание атакой оружием наносит дополнительно 2к6 урона (силовое поле), и цель совершает спасбросок (Мудрость) — при провале она замедляется: не может совершать бонусных действий до конца своего следующего хода. На больших уровнях: +1к6 за каждый уровень ячейки выше 1-го.","save":"Мудрость","atk":false,"mech":"Клеймо","theme":"Времени","orig":true,"pack":"spells6.js"},{"id":"sp6-avatar-teni","n":"Аватар Тени","l":6,"sc":"Преобразование","t":"1 бонусное действие","r":"На себя","c":"ВС","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"4к8 некротика","cl":["Колдун","Волшебник"],"ds":"Вы становитесь аватаром стихии: иммунитет к урону «некротика», полёт 18 м, 30 временных хитов. Бонусным действием в каждый ход вы метаете снаряд (дальнобойная атака заклинанием, 36 м) на 4к8 урона (некротика). На больших уровнях: +10 временных хитов за каждый уровень ячейки выше 6-го.","save":"","atk":true,"mech":"Аватар","theme":"Тени","orig":true,"pack":"spells6.js"},{"id":"sp6-aura-krovi","n":"Аура Крови","l":3,"sc":"Ограждение","t":"1 действие","r":"На себя (3 м)","c":"В","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"2к6 некротика","cl":["Жрец","Паладин","Бард"],"ds":"Вас окружает аура радиусом 3 м. Союзники в ней имеют сопротивление урону «некротика» и преимущество на спасброски от эффектов, из-за которых цель не может восстанавливать хиты до конца своего следующего хода. Враг, начинающий ход в ауре, совершает спасбросок (Телосложение) или получает 2к6 урона (некротика). На больших уровнях: +1к6 за каждый уровень ячейки выше 3-го.","save":"Телосложение","atk":false,"mech":"Аура","theme":"Крови","orig":true,"pack":"spells6.js"},{"id":"sp6-golos-molniy","n":"Голос Молний","l":1,"sc":"Очарование","t":"1 действие","r":"На себя","c":"В","m":"","d":"10 минут","conc":false,"rit":false,"dmg":"—","cl":["Чародей","Бард","Колдун"],"ds":"Ваш голос наполняется силой стихии (молний). Вы совершаете с преимуществом проверки Харизмы против существ, которые вас слышат; одно из них по вашему выбору совершает спасбросок Мудрости — при провале оно не может солгать вам до конца действия заклинания. По окончании существо знает, что на него влияли. На больших уровнях: +1 существо, которое не может лгать за каждый уровень ячейки выше 1-го.","save":"","atk":false,"mech":"Голос","theme":"Молний","orig":true,"pack":"spells6.js"},{"id":"sp6-carstvo-groma","n":"Царство Грома","l":7,"sc":"Вызов","t":"1 минута","r":"Касание","c":"ВСМ","m":"Маленький колокольчик.","d":"1 день","conc":false,"rit":false,"dmg":"—","cl":["Бард","Жрец"],"ds":"Вы и до 8 существ переноситесь в полуплан стихии (грома) площадью 150 м², где вы задаёте погоду, свет и простой рельеф. Несогласное существо может избежать переноса спасброском Харизмы. По окончании все возвращаются туда, откуда ушли. Ячейкой 9 уровня — постоянно, с единственным входом.","save":"Телосложение","atk":false,"mech":"Царство","theme":"Грома","orig":true,"pack":"spells6.js"},{"id":"sp6-perenos-ineya","n":"Перенос Инея","l":3,"sc":"Вызов","t":"1 действие","r":"Касание","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"—","cl":["Волшебник","Друид","Следопыт"],"ds":"Вы и до шести согласных существ, держащихся за руки, перемещаетесь по льду и снегу на расстояние до 150 м в видимое или известное вам место. На больших уровнях: +150 м за каждый уровень ячейки выше 3-го.","save":"","atk":false,"mech":"Перенос","theme":"Инея","orig":true,"pack":"spells6.js"},{"id":"sp6-balzam-plameni","n":"Бальзам Пламени","l":1,"sc":"Воплощение","t":"1 действие","r":"Касание","c":"ВС","m":"","d":"1 минута","conc":false,"rit":false,"dmg":"—","cl":["Друид","Следопыт","Паладин"],"ds":"Существо восстанавливает 1к8 + модификатор заклинательной характеристики хитов и получает сопротивление урону «огонь» на 1 минуту. Не действует на нежить и конструктов. На больших уровнях: +1к8 за каждый уровень ячейки выше 1-го.","save":"","atk":false,"mech":"Бальзам","theme":"Пламени","orig":true,"pack":"spells6.js"},{"id":"sp6-vlast-kostey","n":"Власть Костей","l":8,"sc":"Некромантия","t":"1 действие","r":"На себя (1,5 км)","c":"ВС","m":"","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"6к10 колющий","cl":["Колдун","Жрец"],"ds":"Вы повелеваете стихией (костей) в радиусе 1,5 км: создаёте, гасите, перемещаете и формируете её проявления. Действием вы обрушиваете её на существо в 36 м: спасбросок (Телосложение), 6к10 урона (колющий) при провале и цель становится хрупкой: следующий дробящий урон по ней до конца её следующего хода увеличивается на 1к6, половина при успехе.","save":"Телосложение","atk":false,"mech":"Власть","theme":"Костей","orig":true,"pack":"spells6.js"},{"id":"sp6-burya-pustoty","n":"Буря Пустоты","l":4,"sc":"Вызов","t":"1 действие","r":"90 м","c":"ВСМ","m":"Чёрная жемчужина.","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"3к6 силовое поле","cl":["Чародей","Колдун","Волшебник"],"ds":"Буря (пустоты) в цилиндре радиусом 6 м и высотой 12 м: местность труднопроходимая. Существо, начинающее ход в буре или впервые входящее в неё за ход, совершает спасбросок (Харизма): 3к6 урона (силовое поле) при провале, половина при успехе. На больших уровнях: +1к6 за каждый уровень ячейки выше 4-го.","save":"Харизма","atk":false,"mech":"Буря","theme":"Пустоты","orig":true,"pack":"spells6.js"},{"id":"sp6-sfera-zvezd","n":"Сфера Звёзд","l":2,"sc":"Прорицание","t":"1 действие","r":"18 м","c":"ВСМ","m":"Щепоть звёздной пыли.","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"2к6 излучение","cl":["Бард","Жрец","Волшебник"],"ds":"Сфера (звёзд) диаметром 1,5 м появляется в пределах дистанции. Существо, оканчивающее ход в 1,5 м от неё, совершает спасбросок (Мудрость): 2к6 урона (излучение) при провале, половина при успехе. Бонусным действием сфера перемещается на 9 м; если она врезается в существо, оно совершает спасбросок, и сфера останавливается. На больших уровнях: +1к6 за каждый уровень ячейки выше 2-го.","save":"Мудрость","atk":false,"mech":"Сфера","theme":"Звёзд","orig":true,"pack":"spells6.js"},{"id":"sp6-apokalipsis-razuma","n":"Апокалипсис Разума","l":9,"sc":"Очарование","t":"1 действие","r":"1,5 км","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"14к6+14к6 психический","cl":["Бард","Чародей"],"ds":"Вы выбираете до четырёх точек; от каждой расходится сфера радиусом 12 м. Существо в одной или нескольких сферах совершает один спасбросок (Интеллект): 14к6 урона (психический) плюс 14к6 силовым полем при провале (и цель не может совершать реакции и совершает с помехой следующую проверку Интеллекта), половина при успехе. Предметы и строения в области получают двойной урон.","save":"Интеллект","atk":false,"mech":"Апокалипсис","theme":"Разума","orig":true,"pack":"spells6.js"},{"id":"sp6-vrata-yada","n":"Врата Яда","l":4,"sc":"Ограждение","t":"1 действие","r":"18 м","c":"ВСМ","m":"Жало пчелы.","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"4к10 яд","cl":["Следопыт","Колдун","Чародей"],"ds":"Существо совершает спасбросок Харизмы или проваливается в карман-измерение (яда). Там оно недееспособно. Когда заклинание оканчивается, цель возвращается и получает 4к10 урона (яд). Если концентрация продержалась полную минуту, урон удваивается. На больших уровнях: +1 цель за каждый уровень ячейки выше 4-го.","save":"Харизма","atk":false,"mech":"Врата","theme":"Яда","orig":true,"pack":"spells6.js"},{"id":"sp6-zavesa-voln","n":"Завеса Волн","l":2,"sc":"Вызов","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Концентрация, до 10 минут","conc":true,"rit":false,"dmg":"—","cl":["Чародей","Жрец","Друид"],"ds":"Куб с ребром 6 м заполняется завесой (волн): местность труднопроходимая и слабо заслонённая. Существо, впервые за ход входящее туда, совершает спасбросок (Сила) — при провале оно промокает и сбивается с ног; до конца её следующего хода она уязвима к электричеству. На больших уровнях: +3 м к ребру куба за каждый уровень ячейки выше 2-го.","save":"Сила","atk":false,"mech":"Завеса","theme":"Волн","orig":true,"pack":"spells6.js"},{"id":"sp6-kasanie-vetra","n":"Касание Ветра","l":0,"sc":"Воплощение","t":"1 действие","r":"Касание","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"1к8 звук","cl":["Чародей","Друид","Изобретатель"],"ds":"Рукопашная атака заклинанием: при попадании 1к8 урона (звук), и цель отталкивается на 4,5 м в выбранном вами направлении. Урон увеличивается на одну кость на 5, 11 и 17 уровнях.","save":"","atk":true,"mech":"Касание","theme":"Ветра","orig":true,"pack":"spells6.js"},{"id":"sp6-tropa-kamnya","n":"Тропа Камня","l":4,"sc":"Преобразование","t":"10 минут","r":"Касание","c":"ВСМ","m":"Кусочек гранита.","d":"8 часов","conc":false,"rit":true,"dmg":"—","cl":["Изобретатель","Друид","Волшебник"],"ds":"До 8 согласных существ отправляются в путь сквозь камень: группа проходит через скалу или стену толщиной до 30 м. На время действия скорость путешествия группы удваивается, а случайные столкновения в пути случаются вдвое реже.","save":"","atk":false,"mech":"Тропа","theme":"Камня","orig":true,"pack":"spells6.js"},{"id":"sp6-morok-duhov","n":"Морок Духов","l":2,"sc":"Очарование","t":"1 действие","r":"27 м","c":"ВС","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"—","cl":["Бард","Колдун","Жрец"],"ds":"Существо совершает спасбросок Мудрости. При провале в начале каждого своего хода оно бросает к6: на 1–2 оно атакует ближайшее существо (кроме себя) и больше ничего не делает. В конце хода оно повторяет спасбросок. При каждом провале повторного спасброска цель также испугана вами до конца её следующего хода. На больших уровнях: +1 цель за каждый уровень ячейки выше 2-го.","save":"Мудрость","atk":false,"mech":"Морок","theme":"Духов","orig":true,"pack":"spells6.js"},{"id":"sp6-otmetina-mirazhey","n":"Отметина Миражей","l":0,"sc":"Иллюзия","t":"1 бонусное действие","r":"18 м","c":"С","m":"","d":"1 раунд","conc":false,"rit":false,"dmg":"1к4 психический","cl":["Паладин","Следопыт","Изобретатель"],"ds":"Вы отмечаете существо знаком (миражей). Первое попадание по нему атакой оружием (вашей или союзника) до конца вашего следующего хода наносит дополнительно 1к4 урона (психический). Нельзя накладывать на одно существо чаще раза в раунд. Кость урона растёт до к6, к8 и к10 на 5, 11 и 17 уровнях.","save":"","atk":false,"mech":"Отметина","theme":"Миражей","orig":true,"pack":"spells6.js"},{"id":"sp6-kara-sveta","n":"Кара Света","l":5,"sc":"Воплощение","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"8к8 излучение","cl":["Жрец","Изобретатель","Чародей"],"ds":"Одно существо совершает спасбросок (Телосложение): 8к8 урона (излучение) при провале (и цель излучает тусклый свет в 1,5 м и не может стать невидимой до конца её следующего хода), половина при успехе. Если урон опускает хиты до 0, цель распадается, становясь прахом стихии. На больших уровнях: +1к8 за каждый уровень ячейки выше 5-го.","save":"Телосложение","atk":false,"mech":"Кара","theme":"Света","orig":true,"pack":"spells6.js"},{"id":"sp6-strazh-shipov","n":"Страж Шипов","l":2,"sc":"Вызов","t":"1 действие","r":"9 м","c":"ВСМ","m":"Шип розы.","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"1к8 колющий","cl":["Следопыт","Друид","Колдун"],"ds":"Вы призываете крошечного духа (шипов): КД 14, хиты 10, полёт 9 м, действует в ваш ход. Он может совершать действие Помощь или атаковать (атака заклинанием, 1,5 м, 1к8 урона (колющий)). Реакцией дух бьёт существо, атакующее вас в 1,5 м от него. На больших уровнях: +5 хитов и +1к8 к урону за каждый уровень ячейки выше 2-го.","save":"","atk":true,"mech":"Страж","theme":"Шипов","orig":true,"pack":"spells6.js"},{"id":"sp6-obereg-run","n":"Оберег Рун","l":0,"sc":"Ограждение","t":"1 реакция (когда вы получаете урон)","r":"На себя","c":"С","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"—","cl":["Жрец","Изобретатель","Волшебник"],"ds":"Вы уменьшаете полученный урон на 1к6 + модификатор заклинательной характеристики. Если урон был типа «силовое поле», уменьшение удваивается. Кость растёт до 2к6, 3к6 и 4к6 на 5, 11 и 17 уровнях.","save":"","atk":false,"mech":"Оберег","theme":"Рун","orig":true,"pack":"spells6.js"},{"id":"sp6-svyatilische-vremeni","n":"Святилище Времени","l":5,"sc":"Ограждение","t":"10 минут","r":"Касание","c":"ВСМ","m":"Песчинка из песочных часов.","d":"24 часа","conc":false,"rit":false,"dmg":"—","cl":["Изобретатель","Паладин","Волшебник"],"ds":"Область радиусом 15 м становится святилищем стихии. Союзники в ней получают +1 к КД и спасброскам; враги, входящие в область, совершают спасбросок (Мудрость) — при провале они замедляется: не может совершать бонусных действий до конца своего следующего хода и у них помеха на атаки по союзникам до конца хода. Ячейкой 7+ уровня длится 7 дней, 9 уровня — постоянно.","save":"Мудрость","atk":false,"mech":"Святилище","theme":"Времени","orig":true,"pack":"spells6.js"},{"id":"sp6-vzryv-teni","n":"Взрыв Тени","l":3,"sc":"Иллюзия","t":"1 действие","r":"45 м","c":"ВСМ","m":"Клочок чёрной ткани.","d":"Мгновенная","conc":false,"rit":false,"dmg":"6к6 некротика","cl":["Колдун","Чародей","Бард"],"ds":"Сфера радиусом 6 м: каждое существо совершает спасбросок (Мудрость), получая 6к6 урона (некротика) при провале (и цель окутывается тенью: помеха на проверки Мудрости (Восприятие) и атаки по существам дальше 9 м) или половину при успехе. На больших уровнях: +1к6 за каждый уровень ячейки выше 3-го.","save":"Мудрость","atk":false,"mech":"Взрыв","theme":"Тени","orig":true,"pack":"spells6.js"},{"id":"sp6-volna-krovi","n":"Волна Крови","l":1,"sc":"Некромантия","t":"1 действие","r":"На себя (конус 4,5 м)","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"2к6 некротика","cl":["Чародей","Колдун","Жрец"],"ds":"Существа в конусе совершают спасбросок (Телосложение): при провале 2к6 урона (некротика) и цель не может восстанавливать хиты до конца своего следующего хода; при успехе — половина урона без дополнительного эффекта. На больших уровнях: +1к6 за каждый уровень ячейки выше 1-го.","save":"Телосложение","atk":false,"mech":"Волна","theme":"Крови","orig":true,"pack":"spells6.js"},{"id":"sp6-svyaz-molniy","n":"Связь Молний","l":5,"sc":"Прорицание","t":"10 минут","r":"Неограниченная","c":"ВСМ","m":"Кусочек янтаря.","d":"Концентрация, до 10 минут","conc":true,"rit":true,"dmg":"—","cl":["Изобретатель","Друид","Следопыт"],"ds":"Вы вопрошаете механизм или металл поблизости (он «помнит», кто к нему прикасался), но в любом месте плана, где бывали. Вы видите и слышите место, как если бы находились там, и можете говорить с присутствующими.","save":"","atk":false,"mech":"Связь","theme":"Молний","orig":true,"pack":"spells6.js"},{"id":"sp6-kokon-groma","n":"Кокон Грома","l":3,"sc":"Ограждение","t":"1 действие","r":"18 м","c":"ВС","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"—","cl":["Бард","Чародей","Жрец"],"ds":"Кокон (грома) окружает существо. Согласное существо получает полное укрытие и 2к10 временных хитов. Несогласное совершает спасбросок (Телосложение) — при провале оно опутано, имеет полное укрытие и не может колдовать заклинания с соматическим компонентом; в конце каждого хода повторяет спасбросок. На больших уровнях: +1 цель за каждый уровень ячейки выше 3-го.","save":"Телосложение","atk":false,"mech":"Кокон","theme":"Грома","orig":true,"pack":"spells6.js"},{"id":"sp6-pokrov-ineya","n":"Покров Инея","l":1,"sc":"Ограждение","t":"1 действие","r":"На себя","c":"ВСМ","m":"Кристалл льда.","d":"1 час","conc":false,"rit":false,"dmg":"5 холод","cl":["Паладин","Волшебник","Изобретатель"],"ds":"Вы получаете 5 временных хитов. Пока они есть, существо, попавшее по вам рукопашной атакой, получает 5 урона (холод); у вас сопротивление урону «холод». На больших уровнях: +5 временных хитов и +5 ответного урона за каждый уровень ячейки выше 1-го.","save":"","atk":false,"mech":"Покров","theme":"Инея","orig":true,"pack":"spells6.js"},{"id":"sp6-kolco-plameni","n":"Кольцо Пламени","l":6,"sc":"Воплощение","t":"1 действие","r":"45 м","c":"ВСМ","m":"Щепоть серы.","d":"Концентрация, до 10 минут","conc":true,"rit":false,"dmg":"6к8 огонь","cl":["Чародей","Колдун"],"ds":"Кольцо радиусом до 18 м. Существо внутри не может пересечь кольцо без спасброска (Ловкость): при провале оно получает 6к8 урона (огонь), не проходит и загорается: 1к4 урона (огонь) в начале каждого своего хода, пока не потратит действие на тушение; при успехе — половина урона и проходит. Вы выбираете существ, которых кольцо пропускает. На больших уровнях: +1к8 за каждый уровень ячейки выше 6-го.","save":"Ловкость","atk":false,"mech":"Кольцо","theme":"Пламени","orig":true,"pack":"spells6.js"},{"id":"sp6-duh-kostey","n":"Дух Костей","l":3,"sc":"Вызов","t":"1 действие","r":"27 м","c":"ВСМ","m":"Фаланга пальца.","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"1к8+6 колющий","cl":["Колдун","Жрец","Волшебник"],"ds":"Вы призываете духа (костей) Среднего размера: КД 13 + уровень заклинания, хиты 30 + 10 за уровень выше 3-го, скорость 12 м. Мультиатака: число атак, равное половине уровня заклинания; атака заклинанием +ваш бонус, 1к8 + 3 + уровень урона (колющий). Иммунитет к урону «колющий». Действует сразу после вас. На больших уровнях: +10 хитов и +1 КД за каждый уровень ячейки выше 3-го.","save":"","atk":true,"mech":"Дух","theme":"Костей","orig":true,"pack":"spells6.js"},{"id":"sp6-kleymo-pustoty","n":"Клеймо Пустоты","l":1,"sc":"Вызов","t":"1 бонусное действие","r":"На себя","c":"В","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"2к6 силовое поле","cl":["Следопыт","Паладин","Изобретатель"],"ds":"Следующее ваше попадание атакой оружием наносит дополнительно 2к6 урона (силовое поле), и цель совершает спасбросок (Харизма) — при провале она не может телепортироваться и перемещаться между планами до конца её следующего хода. На больших уровнях: +1к6 за каждый уровень ячейки выше 1-го.","save":"Харизма","atk":false,"mech":"Клеймо","theme":"Пустоты","orig":true,"pack":"spells6.js"},{"id":"sp6-avatar-zvezd","n":"Аватар Звёзд","l":6,"sc":"Преобразование","t":"1 бонусное действие","r":"На себя","c":"ВС","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"4к8 излучение","cl":["Бард","Жрец"],"ds":"Вы становитесь аватаром стихии: иммунитет к урону «излучение», полёт 18 м, 30 временных хитов. Бонусным действием в каждый ход вы метаете снаряд (дальнобойная атака заклинанием, 36 м) на 4к8 урона (излучение). На больших уровнях: +10 временных хитов за каждый уровень ячейки выше 6-го.","save":"","atk":true,"mech":"Аватар","theme":"Звёзд","orig":true,"pack":"spells6.js"},{"id":"sp6-aura-razuma","n":"Аура Разума","l":3,"sc":"Ограждение","t":"1 действие","r":"На себя (3 м)","c":"В","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"2к6 психический","cl":["Бард","Паладин","Следопыт"],"ds":"Вас окружает аура радиусом 3 м. Союзники в ней имеют сопротивление урону «психический» и преимущество на спасброски от эффектов, из-за которых цель не может совершать реакции и совершает с помехой следующую проверку Интеллекта. Враг, начинающий ход в ауре, совершает спасбросок (Интеллект) или получает 2к6 урона (психический). На больших уровнях: +1к6 за каждый уровень ячейки выше 3-го.","save":"Интеллект","atk":false,"mech":"Аура","theme":"Разума","orig":true,"pack":"spells6.js"},{"id":"sp6-golos-yada","n":"Голос Яда","l":1,"sc":"Очарование","t":"1 действие","r":"На себя","c":"В","m":"","d":"10 минут","conc":false,"rit":false,"dmg":"—","cl":["Колдун","Чародей","Бард"],"ds":"Ваш голос наполняется силой стихии (яда). Вы совершаете с преимуществом проверки Харизмы против существ, которые вас слышат; одно из них по вашему выбору совершает спасбросок Мудрости — при провале оно не может солгать вам до конца действия заклинания. По окончании существо знает, что на него влияли. На больших уровнях: +1 существо, которое не может лгать за каждый уровень ячейки выше 1-го.","save":"","atk":false,"mech":"Голос","theme":"Яда","orig":true,"pack":"spells6.js"},{"id":"sp6-carstvo-voln","n":"Царство Волн","l":7,"sc":"Вызов","t":"1 минута","r":"Касание","c":"ВСМ","m":"Морская ракушка.","d":"1 день","conc":false,"rit":false,"dmg":"—","cl":["Жрец","Друид"],"ds":"Вы и до 8 существ переноситесь в полуплан стихии (волн) площадью 150 м², где вы задаёте погоду, свет и простой рельеф. Несогласное существо может избежать переноса спасброском Харизмы. По окончании все возвращаются туда, откуда ушли. Ячейкой 9 уровня — постоянно, с единственным входом.","save":"Сила","atk":false,"mech":"Царство","theme":"Волн","orig":true,"pack":"spells6.js"},{"id":"sp6-perenos-vetra","n":"Перенос Ветра","l":3,"sc":"Вызов","t":"1 действие","r":"Касание","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"—","cl":["Следопыт","Друид","Паладин"],"ds":"Вы и до шести согласных существ, держащихся за руки, перемещаетесь на ветру на расстояние до 150 м в видимое или известное вам место. На больших уровнях: +150 м за каждый уровень ячейки выше 3-го.","save":"","atk":false,"mech":"Перенос","theme":"Ветра","orig":true,"pack":"spells6.js"},{"id":"sp6-balzam-kamnya","n":"Бальзам Камня","l":1,"sc":"Воплощение","t":"1 действие","r":"Касание","c":"ВС","m":"","d":"1 минута","conc":false,"rit":false,"dmg":"—","cl":["Друид","Следопыт","Паладин"],"ds":"Существо восстанавливает 1к8 + модификатор заклинательной характеристики хитов и получает сопротивление урону «дробящий» на 1 минуту. Не действует на нежить и конструктов. На больших уровнях: +1к8 за каждый уровень ячейки выше 1-го.","save":"","atk":false,"mech":"Бальзам","theme":"Камня","orig":true,"pack":"spells6.js"},{"id":"sp6-slovo-duhov","n":"Слово Духов","l":8,"sc":"Очарование","t":"1 действие","r":"На себя (18 м)","c":"В","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"13к6 психический","cl":["Бард","Колдун"],"ds":"Вы произносите истинное слово (духов). Каждый враг в 18 м, слышащий вас, совершает спасбросок Харизмы: 13к6 урона (психический) и ошеломление до конца вашего следующего хода при провале, половина урона при успехе.","save":"Харизма","atk":false,"mech":"Слово","theme":"Духов","orig":true,"pack":"spells6.js"},{"id":"sp6-oblik-mirazhey","n":"Облик Миражей","l":4,"sc":"Преобразование","t":"1 действие","r":"На себя","c":"ВС","m":"","d":"Концентрация, до 10 минут","conc":true,"rit":false,"dmg":"2к8 психический","cl":["Бард","Колдун","Волшебник"],"ds":"Вы принимаете облик (миражей): сопротивление урону «психический» и немагическому оружию, скорость полёта или лазания 12 м, а действием вы совершаете две рукопашные атаки заклинанием по 2к8 урона (психический). Попадание: цель видит ложные образы: помеха на следующий бросок атаки до конца её следующего хода. На больших уровнях: +1к8 к одной атаке за каждый уровень ячейки выше 4-го.","save":"","atk":true,"mech":"Облик","theme":"Миражей","orig":true,"pack":"spells6.js"},{"id":"sp6-cep-sveta","n":"Цепь Света","l":2,"sc":"Воплощение","t":"1 действие","r":"27 м","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"3к8 излучение","cl":["Жрец","Чародей","Друид"],"ds":"Дальнобойная атака заклинанием: 3к8 урона (излучение) при попадании. Затем цепь перескакивает на второе существо в 3 м от первой цели: оно совершает спасбросок (Телосложение) или получает половину этого урона. На больших уровнях: +1к8 и +1 перескок за каждый уровень ячейки выше 2-го.","save":"Телосложение","atk":true,"mech":"Цепь","theme":"Света","orig":true,"pack":"spells6.js"},{"id":"sp6-iskra-shipov","n":"Искра Шипов","l":0,"sc":"Преобразование","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"1к10 колющий","cl":["Друид","Бард","Колдун"],"ds":"Дальнобойная атака заклинанием по существу или предмету: при попадании 1к10 урона (колющий). Предмет, который никто не несёт, получает двойной урон. Урон увеличивается на одну кость на 5, 11 и 17 уровнях.","save":"","atk":true,"mech":"Искра","theme":"Шипов","orig":true,"pack":"spells6.js"},{"id":"sp6-stena-run","n":"Стена Рун","l":4,"sc":"Ограждение","t":"1 действие","r":"36 м","c":"ВСМ","m":"Резец и кусочек кости.","d":"Концентрация, до 10 минут","conc":true,"rit":false,"dmg":"5к8 силовое поле","cl":["Жрец","Чародей","Волшебник"],"ds":"Стена (рун) длиной до 18 м, высотой 6 м и толщиной 30 см (или кольцо диаметром 6 м). Существо, впервые за ход проходящее сквозь стену или оканчивающее ход в ней, совершает спасбросок (Интеллект): 5к8 урона (силовое поле) при провале (и цель получает светящуюся руну: следующая атака по ней до конца вашего следующего хода получает +1к4 к броску), половина при успехе. Стена — слабо заслоняет обзор. На больших уровнях: +1к8 за каждый уровень ячейки выше 4-го.","save":"Интеллект","atk":false,"mech":"Стена","theme":"Рун","orig":true,"pack":"spells6.js"},{"id":"sp6-oruzhie-vremeni","n":"Оружие Времени","l":2,"sc":"Преобразование","t":"1 бонусное действие","r":"Касание","c":"ВС","m":"","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"1к6 силовое поле","cl":["Изобретатель","Паладин","Следопыт"],"ds":"Немагическое оружие становится магическим с бонусом +1 к атаке и наносит дополнительно 1к6 урона (силовое поле). Один раз в ход при попадании владелец может заставить цель совершить спасбросок (Мудрость): при провале она замедляется: не может совершать бонусных действий до конца своего следующего хода. Ячейкой 4–5 уровня бонус +2, 6+ уровня — +3.","save":"","atk":false,"mech":"Оружие","theme":"Времени","orig":true,"pack":"spells6.js"},{"id":"sp6-vspyshka-teni","n":"Вспышка Тени","l":0,"sc":"Иллюзия","t":"1 действие","r":"На себя (1,5 м)","c":"С","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"1к6 некротика","cl":["Колдун","Волшебник","Изобретатель"],"ds":"Каждое существо по вашему выбору в пределах 1,5 м совершает спасбросок (Мудрость), получая 1к6 урона (некротика) при провале. Не требует видеть цели. Урон увеличивается на одну кость на 5, 11 и 17 уровнях.","save":"Мудрость","atk":false,"mech":"Вспышка","theme":"Тени","orig":true,"pack":"spells6.js"},{"id":"sp6-proklyatie-krovi","n":"Проклятие Крови","l":4,"sc":"Некромантия","t":"1 действие","r":"Касание","c":"ВС","m":"","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"2к6 некротика","cl":["Чародей","Колдун","Жрец"],"ds":"Цель совершает спасбросок Мудрости. При провале ваши атаки и заклинания наносят ей дополнительно 2к6 урона (некротика), а в начале каждого её хода она бросает к4: на 1 она не может восстанавливать хиты до конца своего следующего хода. «Снятие проклятия» оканчивает эффект. Ячейкой 5 уровня — 8 часов без концентрации, 7+ уровня — 24 часа.","save":"Мудрость","atk":false,"mech":"Проклятие","theme":"Крови","orig":true,"pack":"spells6.js"},{"id":"sp6-slepok-molniy","n":"Слепок Молний","l":2,"sc":"Преобразование","t":"1 минута","r":"Касание","c":"ВСМ","m":"Кусочек янтаря.","d":"8 часов","conc":false,"rit":false,"dmg":"—","cl":["Изобретатель","Друид","Волшебник"],"ds":"Вы создаёте немагический предмет из медной проволоки, гудящей от заряда размером до куба 1,5 м: инструмент, мост, лестницу, ящик или простое оружие. Предмет имеет КД 15 и 30 хитов; через 8 часов он рассыпается. Ячейкой 4+ уровня предмет держится 24 часа, 6+ уровня — постоянно.","save":"","atk":false,"mech":"Слепок","theme":"Молний","orig":true,"pack":"spells6.js"},{"id":"sp6-maloe-chudo-groma","n":"Малое Чудо Грома","l":0,"sc":"Воплощение","t":"1 действие","r":"9 м","c":"В","m":"","d":"До 1 часа","conc":false,"rit":false,"dmg":"—","cl":["Бард","Жрец","Друид"],"ds":"Вы творите мелкое чудо: создать гулкий удар, слышимый за 90 м, или заглушить один звук до шёпота. Одновременно активны не более трёх эффектов; вы можете окончить любой действием.","save":"","atk":false,"mech":"Малое Чудо","theme":"Грома","orig":true,"pack":"spells6.js"},{"id":"sp6-legion-ineya","n":"Легион Инея","l":5,"sc":"Вызов","t":"1 действие","r":"27 м","c":"ВСМ","m":"Кристалл льда.","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"2к6 холод","cl":["Следопыт","Друид","Волшебник"],"ds":"Появляются четыре духа (инея): Маленькие, КД 15, хиты 20, скорость 12 м, иммунитет к урону «холод». Каждый атакует заклинанием 1,5 м на 2к6 урона (холод). Действуют в вашу инициативу по вашим мысленным командам (без действия). На больших уровнях: +1 дух за каждый уровень ячейки выше 5-го.","save":"","atk":true,"mech":"Легион","theme":"Инея","orig":true,"pack":"spells6.js"},{"id":"sp6-pechat-plameni","n":"Печать Пламени","l":2,"sc":"Ограждение","t":"10 минут","r":"Касание","c":"ВСМ","m":"Щепоть серы.","d":"8 часов","conc":false,"rit":true,"dmg":"3к6 огонь","cl":["Изобретатель","Паладин","Волшебник"],"ds":"Вы чертите печать на поверхности или проходе (до 6 м). Когда существо, не названное вами, пересекает её, вы мысленно пробуждаетесь/узнаёте об этом (если вы в пределах 1,5 км), а нарушитель совершает спасбросок (Ловкость): 3к6 урона (огонь) при провале, половина при успехе. На больших уровнях: +1к6 за каждый уровень ячейки выше 2-го.","save":"Ловкость","atk":false,"mech":"Печать","theme":"Пламени","orig":true,"pack":"spells6.js"},{"id":"sp6-obereg-kostey","n":"Оберег Костей","l":0,"sc":"Некромантия","t":"1 реакция (когда вы получаете урон)","r":"На себя","c":"С","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"—","cl":["Жрец","Волшебник","Паладин"],"ds":"Вы уменьшаете полученный урон на 1к6 + модификатор заклинательной характеристики. Если урон был типа «колющий», уменьшение удваивается. Кость растёт до 2к6, 3к6 и 4к6 на 5, 11 и 17 уровнях.","save":"","atk":false,"mech":"Оберег","theme":"Костей","orig":true,"pack":"spells6.js"},{"id":"sp6-svyatilische-pustoty","n":"Святилище Пустоты","l":5,"sc":"Ограждение","t":"10 минут","r":"Касание","c":"ВСМ","m":"Чёрная жемчужина.","d":"24 часа","conc":false,"rit":false,"dmg":"—","cl":["Паладин","Изобретатель","Волшебник"],"ds":"Область радиусом 15 м становится святилищем стихии. Союзники в ней получают +1 к КД и спасброскам; враги, входящие в область, совершают спасбросок (Харизма) — при провале они не может телепортироваться и перемещаться между планами до конца её следующего хода и у них помеха на атаки по союзникам до конца хода. Ячейкой 7+ уровня длится 7 дней, 9 уровня — постоянно.","save":"Харизма","atk":false,"mech":"Святилище","theme":"Пустоты","orig":true,"pack":"spells6.js"},{"id":"sp6-vzryv-zvezd","n":"Взрыв Звёзд","l":3,"sc":"Прорицание","t":"1 действие","r":"45 м","c":"ВСМ","m":"Щепоть звёздной пыли.","d":"Мгновенная","conc":false,"rit":false,"dmg":"6к6 излучение","cl":["Бард","Жрец","Друид"],"ds":"Сфера радиусом 6 м: каждое существо совершает спасбросок (Мудрость), получая 6к6 урона (излучение) при провале (и цель очерчивается звёздным светом: атаки по ней совершаются с преимуществом до конца её следующего хода) или половину при успехе. На больших уровнях: +1к6 за каждый уровень ячейки выше 3-го.","save":"Мудрость","atk":false,"mech":"Взрыв","theme":"Звёзд","orig":true,"pack":"spells6.js"},{"id":"sp6-volna-razuma","n":"Волна Разума","l":1,"sc":"Очарование","t":"1 действие","r":"На себя (конус 4,5 м)","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"2к6 психический","cl":["Бард","Чародей","Колдун"],"ds":"Существа в конусе совершают спасбросок (Интеллект): при провале 2к6 урона (психический) и цель не может совершать реакции и совершает с помехой следующую проверку Интеллекта; при успехе — половина урона без дополнительного эффекта. На больших уровнях: +1к6 за каждый уровень ячейки выше 1-го.","save":"Интеллект","atk":false,"mech":"Волна","theme":"Разума","orig":true,"pack":"spells6.js"},{"id":"sp6-svyaz-yada","n":"Связь Яда","l":5,"sc":"Прорицание","t":"10 минут","r":"Неограниченная","c":"ВСМ","m":"Жало пчелы.","d":"Концентрация, до 10 минут","conc":true,"rit":true,"dmg":"—","cl":["Следопыт","Изобретатель","Колдун"],"ds":"Вы вопрошаете яд или болезнь (они говорят, кем и когда созданы), но в любом месте плана, где бывали. Вы видите и слышите место, как если бы находились там, и можете говорить с присутствующими.","save":"","atk":false,"mech":"Связь","theme":"Яда","orig":true,"pack":"spells6.js"},{"id":"sp6-kokon-voln","n":"Кокон Волн","l":3,"sc":"Ограждение","t":"1 действие","r":"18 м","c":"ВС","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"—","cl":["Чародей","Жрец","Друид"],"ds":"Кокон (волн) окружает существо. Согласное существо получает полное укрытие и 2к10 временных хитов. Несогласное совершает спасбросок (Сила) — при провале оно опутано, имеет полное укрытие и не может колдовать заклинания с соматическим компонентом; в конце каждого хода повторяет спасбросок. На больших уровнях: +1 цель за каждый уровень ячейки выше 3-го.","save":"Сила","atk":false,"mech":"Кокон","theme":"Волн","orig":true,"pack":"spells6.js"},{"id":"sp6-pokrov-vetra","n":"Покров Ветра","l":1,"sc":"Ограждение","t":"1 действие","r":"На себя","c":"ВСМ","m":"Перо.","d":"1 час","conc":false,"rit":false,"dmg":"5 звук","cl":["Паладин","Жрец","Волшебник"],"ds":"Вы получаете 5 временных хитов. Пока они есть, существо, попавшее по вам рукопашной атакой, получает 5 урона (звук); у вас сопротивление урону «звук». На больших уровнях: +5 временных хитов и +5 ответного урона за каждый уровень ячейки выше 1-го.","save":"","atk":false,"mech":"Покров","theme":"Ветра","orig":true,"pack":"spells6.js"},{"id":"sp6-kolco-kamnya","n":"Кольцо Камня","l":6,"sc":"Преобразование","t":"1 действие","r":"45 м","c":"ВСМ","m":"Кусочек гранита.","d":"Концентрация, до 10 минут","conc":true,"rit":false,"dmg":"6к8 дробящий","cl":["Волшебник","Друид"],"ds":"Кольцо радиусом до 18 м. Существо внутри не может пересечь кольцо без спасброска (Сила): при провале оно получает 6к8 урона (дробящий), не проходит и сбивается с ног, если она Большая или меньше; при успехе — половина урона и проходит. Вы выбираете существ, которых кольцо пропускает. На больших уровнях: +1к8 за каждый уровень ячейки выше 6-го.","save":"Сила","atk":false,"mech":"Кольцо","theme":"Камня","orig":true,"pack":"spells6.js"},{"id":"sp6-ubezhische-duhov","n":"Убежище Духов","l":3,"sc":"Ограждение","t":"1 минута","r":"На себя (полусфера 3 м)","c":"ВСМ","m":"Благовония.","d":"8 часов","conc":false,"rit":true,"dmg":"—","cl":["Бард","Колдун","Жрец"],"ds":"Над вами возникает неподвижное убежище для 9 Средних существ: круг духов-стражей, будящих вас при появлении чужаков. Существа и предметы внутри при сотворении могут свободно выходить и входить; прочие — нет. Магия не проходит сквозь стены.","save":"","atk":false,"mech":"Убежище","theme":"Духов","orig":true,"pack":"spells6.js"},{"id":"sp6-chute-mirazhey","n":"Чутьё Миражей","l":1,"sc":"Прорицание","t":"1 действие","r":"На себя (9 м)","c":"ВС","m":"","d":"Концентрация, до 10 минут","conc":true,"rit":true,"dmg":"—","cl":["Бард","Колдун","Следопыт"],"ds":"Вы чувствуете иллюзии, переодетых существ и ложные стены в пределах 9 м и знаете их направление. Чутьё проходит сквозь большинство преград, но блокируется 30 см камня, 2,5 см металла или тонким листом свинца.","save":"","atk":false,"mech":"Чутьё","theme":"Миражей","orig":true,"pack":"spells6.js"},{"id":"sp6-katastrofa-sveta","n":"Катастрофа Света","l":7,"sc":"Воплощение","t":"1 действие","r":"300 м","c":"ВСМ","m":"Святой символ.","d":"Мгновенная","conc":false,"rit":false,"dmg":"12к6 излучение","cl":["Жрец","Бард"],"ds":"Сфера радиусом 12 м: существа совершают спасбросок (Телосложение) — 12к6 урона (излучение) при провале (и цель излучает тусклый свет в 1,5 м и не может стать невидимой до конца её следующего хода), половина при успехе. Местность становится труднопроходимой на 1 час. На больших уровнях: +1к6 за каждый уровень ячейки выше 7-го.","save":"Телосложение","atk":false,"mech":"Катастрофа","theme":"Света","orig":true,"pack":"spells6.js"},{"id":"sp6-opros-shipov","n":"Опрос Шипов","l":3,"sc":"Прорицание","t":"10 минут","r":"Касание","c":"ВСМ","m":"Шип розы.","d":"10 минут","conc":false,"rit":true,"dmg":"—","cl":["Следопыт","Друид","Паладин"],"ds":"Вы обращаетесь к стихии: вопрошаете ближайшее растение (оно помнит, кто проходил мимо за неделю). Вы можете задать до трёх вопросов и получаете короткие правдивые ответы, ограниченные тем, что могла «видеть» стихия.","save":"","atk":false,"mech":"Опрос","theme":"Шипов","orig":true,"pack":"spells6.js"},{"id":"sp6-shag-run","n":"Шаг Рун","l":1,"sc":"Вызов","t":"1 бонусное действие","r":"На себя","c":"В","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"1к6 силовое поле","cl":["Жрец","Изобретатель","Волшебник"],"ds":"Вы телепортируетесь на 9 м в видимое свободное место. Каждое существо в 1,5 м от точки отправления совершает спасбросок (Интеллект) или получает 1к6 урона (силовое поле). На больших уровнях: +3 м дистанции и +1к6 за каждый уровень ячейки выше 1-го.","save":"Интеллект","atk":false,"mech":"Шаг","theme":"Рун","orig":true,"pack":"spells6.js"},{"id":"sp6-vlast-vremeni","n":"Власть Времени","l":8,"sc":"Преобразование","t":"1 действие","r":"На себя (1,5 км)","c":"ВС","m":"","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"6к10 силовое поле","cl":["Бард","Волшебник"],"ds":"Вы повелеваете стихией (времени) в радиусе 1,5 км: создаёте, гасите, перемещаете и формируете её проявления. Действием вы обрушиваете её на существо в 36 м: спасбросок (Мудрость), 6к10 урона (силовое поле) при провале и цель замедляется: не может совершать бонусных действий до конца своего следующего хода, половина при успехе.","save":"Мудрость","atk":false,"mech":"Власть","theme":"Времени","orig":true,"pack":"spells6.js"},{"id":"sp6-burya-teni","n":"Буря Тени","l":4,"sc":"Иллюзия","t":"1 действие","r":"90 м","c":"ВСМ","m":"Клочок чёрной ткани.","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"3к6 некротика","cl":["Колдун","Чародей","Волшебник"],"ds":"Буря (тени) в цилиндре радиусом 6 м и высотой 12 м: местность труднопроходимая. Существо, начинающее ход в буре или впервые входящее в неё за ход, совершает спасбросок (Мудрость): 3к6 урона (некротика) при провале, половина при успехе. На больших уровнях: +1к6 за каждый уровень ячейки выше 4-го.","save":"Мудрость","atk":false,"mech":"Буря","theme":"Тени","orig":true,"pack":"spells6.js"},{"id":"sp6-sfera-krovi","n":"Сфера Крови","l":2,"sc":"Некромантия","t":"1 действие","r":"18 м","c":"ВСМ","m":"Капля вашей крови.","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"2к6 некротика","cl":["Чародей","Колдун","Жрец"],"ds":"Сфера (крови) диаметром 1,5 м появляется в пределах дистанции. Существо, оканчивающее ход в 1,5 м от неё, совершает спасбросок (Телосложение): 2к6 урона (некротика) при провале, половина при успехе. Бонусным действием сфера перемещается на 9 м; если она врезается в существо, оно совершает спасбросок, и сфера останавливается. На больших уровнях: +1к6 за каждый уровень ячейки выше 2-го.","save":"Телосложение","atk":false,"mech":"Сфера","theme":"Крови","orig":true,"pack":"spells6.js"},{"id":"sp6-apokalipsis-molniy","n":"Апокалипсис Молний","l":9,"sc":"Воплощение","t":"1 действие","r":"1,5 км","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"14к6+14к6 электричество","cl":["Чародей","Друид"],"ds":"Вы выбираете до четырёх точек; от каждой расходится сфера радиусом 12 м. Существо в одной или нескольких сферах совершает один спасбросок (Ловкость): 14к6 урона (электричество) плюс 14к6 силовым полем при провале (и цель не может совершать реакции до начала своего следующего хода), половина при успехе. Предметы и строения в области получают двойной урон.","save":"Ловкость","atk":false,"mech":"Апокалипсис","theme":"Молний","orig":true,"pack":"spells6.js"},{"id":"sp6-vrata-groma","n":"Врата Грома","l":4,"sc":"Ограждение","t":"1 действие","r":"18 м","c":"ВСМ","m":"Маленький колокольчик.","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"4к10 звук","cl":["Чародей","Бард","Жрец"],"ds":"Существо совершает спасбросок Харизмы или проваливается в карман-измерение (грома). Там оно недееспособно. Когда заклинание оканчивается, цель возвращается и получает 4к10 урона (звук). Если концентрация продержалась полную минуту, урон удваивается. На больших уровнях: +1 цель за каждый уровень ячейки выше 4-го.","save":"Харизма","atk":false,"mech":"Врата","theme":"Грома","orig":true,"pack":"spells6.js"},{"id":"sp6-zavesa-ineya","n":"Завеса Инея","l":2,"sc":"Воплощение","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Концентрация, до 10 минут","conc":true,"rit":false,"dmg":"—","cl":["Чародей","Друид","Следопыт"],"ds":"Куб с ребром 6 м заполняется завесой (инея): местность труднопроходимая и слабо заслонённая. Существо, впервые за ход входящее туда, совершает спасбросок (Телосложение) — при провале оно покрывается коркой льда: скорость уменьшается на 3 м до конца её следующего хода. На больших уровнях: +3 м к ребру куба за каждый уровень ячейки выше 2-го.","save":"Телосложение","atk":false,"mech":"Завеса","theme":"Инея","orig":true,"pack":"spells6.js"},{"id":"sp6-kasanie-plameni","n":"Касание Пламени","l":0,"sc":"Воплощение","t":"1 действие","r":"Касание","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"1к8 огонь","cl":["Изобретатель","Чародей","Колдун"],"ds":"Рукопашная атака заклинанием: при попадании 1к8 урона (огонь), и цель загорается: 1к4 урона (огонь) в начале каждого своего хода, пока не потратит действие на тушение. Урон увеличивается на одну кость на 5, 11 и 17 уровнях.","save":"","atk":true,"mech":"Касание","theme":"Пламени","orig":true,"pack":"spells6.js"},{"id":"sp6-stena-kostey","n":"Стена Костей","l":4,"sc":"Некромантия","t":"1 действие","r":"36 м","c":"ВСМ","m":"Фаланга пальца.","d":"Концентрация, до 10 минут","conc":true,"rit":false,"dmg":"5к8 колющий","cl":["Колдун","Жрец","Волшебник"],"ds":"Стена (костей) длиной до 18 м, высотой 6 м и толщиной 30 см (или кольцо диаметром 6 м). Существо, впервые за ход проходящее сквозь стену или оканчивающее ход в ней, совершает спасбросок (Телосложение): 5к8 урона (колющий) при провале (и цель становится хрупкой: следующий дробящий урон по ней до конца её следующего хода увеличивается на 1к6), половина при успехе. Стена — слабо заслоняет обзор. На больших уровнях: +1к8 за каждый уровень ячейки выше 4-го.","save":"Телосложение","atk":false,"mech":"Стена","theme":"Костей","orig":true,"pack":"spells6.js"},{"id":"sp6-oruzhie-pustoty","n":"Оружие Пустоты","l":2,"sc":"Преобразование","t":"1 бонусное действие","r":"Касание","c":"ВС","m":"","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"1к6 силовое поле","cl":["Паладин","Следопыт","Изобретатель"],"ds":"Немагическое оружие становится магическим с бонусом +1 к атаке и наносит дополнительно 1к6 урона (силовое поле). Один раз в ход при попадании владелец может заставить цель совершить спасбросок (Харизма): при провале она не может телепортироваться и перемещаться между планами до конца её следующего хода. Ячейкой 4–5 уровня бонус +2, 6+ уровня — +3.","save":"","atk":false,"mech":"Оружие","theme":"Пустоты","orig":true,"pack":"spells6.js"},{"id":"sp6-vspyshka-zvezd","n":"Вспышка Звёзд","l":0,"sc":"Прорицание","t":"1 действие","r":"На себя (1,5 м)","c":"С","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"1к6 излучение","cl":["Жрец","Бард","Друид"],"ds":"Каждое существо по вашему выбору в пределах 1,5 м совершает спасбросок (Мудрость), получая 1к6 урона (излучение) при провале. Не требует видеть цели. Урон увеличивается на одну кость на 5, 11 и 17 уровнях.","save":"Мудрость","atk":false,"mech":"Вспышка","theme":"Звёзд","orig":true,"pack":"spells6.js"},{"id":"sp6-proklyatie-razuma","n":"Проклятие Разума","l":4,"sc":"Некромантия","t":"1 действие","r":"Касание","c":"ВС","m":"","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"2к6 психический","cl":["Чародей","Бард","Колдун"],"ds":"Цель совершает спасбросок Мудрости. При провале ваши атаки и заклинания наносят ей дополнительно 2к6 урона (психический), а в начале каждого её хода она бросает к4: на 1 она не может совершать реакции и совершает с помехой следующую проверку Интеллекта. «Снятие проклятия» оканчивает эффект. Ячейкой 5 уровня — 8 часов без концентрации, 7+ уровня — 24 часа.","save":"Мудрость","atk":false,"mech":"Проклятие","theme":"Разума","orig":true,"pack":"spells6.js"},{"id":"sp6-slepok-yada","n":"Слепок Яда","l":2,"sc":"Преобразование","t":"1 минута","r":"Касание","c":"ВСМ","m":"Жало пчелы.","d":"8 часов","conc":false,"rit":false,"dmg":"—","cl":["Следопыт","Колдун","Изобретатель"],"ds":"Вы создаёте немагический предмет из ядовитого хитина (касание без перчаток — 1 урон ядом) размером до куба 1,5 м: инструмент, мост, лестницу, ящик или простое оружие. Предмет имеет КД 15 и 30 хитов; через 8 часов он рассыпается. Ячейкой 4+ уровня предмет держится 24 часа, 6+ уровня — постоянно.","save":"","atk":false,"mech":"Слепок","theme":"Яда","orig":true,"pack":"spells6.js"},{"id":"sp6-maloe-chudo-voln","n":"Малое Чудо Волн","l":0,"sc":"Вызов","t":"1 действие","r":"9 м","c":"В","m":"","d":"До 1 часа","conc":false,"rit":false,"dmg":"—","cl":["Жрец","Друид","Паладин"],"ds":"Вы творите мелкое чудо: создать до 4 л пресной воды, очистить её или вызвать небольшую волну в водоёме. Одновременно активны не более трёх эффектов; вы можете окончить любой действием.","save":"","atk":false,"mech":"Малое Чудо","theme":"Волн","orig":true,"pack":"spells6.js"},{"id":"sp6-legion-vetra","n":"Легион Ветра","l":5,"sc":"Вызов","t":"1 действие","r":"27 м","c":"ВСМ","m":"Перо.","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"2к6 звук","cl":["Следопыт","Друид","Волшебник"],"ds":"Появляются четыре духа (ветра): Маленькие, КД 15, хиты 20, скорость 12 м, иммунитет к урону «звук». Каждый атакует заклинанием 1,5 м на 2к6 урона (звук). Действуют в вашу инициативу по вашим мысленным командам (без действия). На больших уровнях: +1 дух за каждый уровень ячейки выше 5-го.","save":"","atk":true,"mech":"Легион","theme":"Ветра","orig":true,"pack":"spells6.js"},{"id":"sp6-pechat-kamnya","n":"Печать Камня","l":2,"sc":"Ограждение","t":"10 минут","r":"Касание","c":"ВСМ","m":"Кусочек гранита.","d":"8 часов","conc":false,"rit":true,"dmg":"3к6 дробящий","cl":["Изобретатель","Паладин","Волшебник"],"ds":"Вы чертите печать на поверхности или проходе (до 6 м). Когда существо, не названное вами, пересекает её, вы мысленно пробуждаетесь/узнаёте об этом (если вы в пределах 1,5 км), а нарушитель совершает спасбросок (Сила): 3к6 урона (дробящий) при провале, половина при успехе. На больших уровнях: +1к6 за каждый уровень ячейки выше 2-го.","save":"Сила","atk":false,"mech":"Печать","theme":"Камня","orig":true,"pack":"spells6.js"},{"id":"sp6-kope-duhov","n":"Копьё Духов","l":1,"sc":"Вызов","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"2к10 психический","cl":["Бард","Колдун","Жрец"],"ds":"Дальнобойная атака заклинанием: при попадании 2к10 урона (психический). При критическом попадании копьё пробивает цель и поражает второе существо в 3 м позади неё (обычный бросок атаки). На больших уровнях: +1к10 за каждый уровень ячейки выше 1-го.","save":"","atk":true,"mech":"Копьё","theme":"Духов","orig":true,"pack":"spells6.js"},{"id":"sp6-dvoynik-mirazhey","n":"Двойник Миражей","l":5,"sc":"Иллюзия","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"4к6 психический","cl":["Бард","Колдун","Следопыт"],"ds":"Вы создаёте двойника из иллюзии, ставшей вещественной. Он двигается по вашей воле (бонусное действие, 9 м), вы видите и слышите его органами чувств, и ваши заклинания могут исходить от него. Двойник имеет КД 14 и 1 хит; при уничтожении взрывается: 4к6 урона (психический) в 3 м.","save":"","atk":false,"mech":"Двойник","theme":"Миражей","orig":true,"pack":"spells6.js"},{"id":"sp6-potok-sveta","n":"Поток Света","l":3,"sc":"Воплощение","t":"1 действие","r":"На себя (линия 30 м)","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"7к6 излучение","cl":["Жрец","Чародей","Бард"],"ds":"Линия длиной 30 м и шириной 1,5 м. Существа на линии совершают спасбросок (Телосложение): 7к6 урона (излучение) при провале, половина при успехе. Поток игнорирует укрытие на половину и на три четверти. На больших уровнях: +1к6 за каждый уровень ячейки выше 3-го.","save":"Телосложение","atk":false,"mech":"Поток","theme":"Света","orig":true,"pack":"spells6.js"},{"id":"sp6-uzy-shipov","n":"Узы Шипов","l":1,"sc":"Очарование","t":"1 действие","r":"18 м","c":"ВСМ","m":"Шип розы.","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"1к4 колющий","cl":["Следопыт","Друид","Паладин"],"ds":"Узы (шипов) охватывают существо: спасбросок (Сила) или оно опутано. В конце каждого своего хода цель повторяет спасбросок, оканчивая эффект при успехе. Пока цель опутана, она получает 1к4 урона (колющий) в начале каждого своего хода. На больших уровнях: +1 цель за каждый уровень ячейки выше 1-го.","save":"Сила","atk":false,"mech":"Узы","theme":"Шипов","orig":true,"pack":"spells6.js"},{"id":"sp6-raspad-run","n":"Распад Рун","l":6,"sc":"Ограждение","t":"1 действие","r":"18 м","c":"ВСМ","m":"Резец и кусочек кости.","d":"Мгновенная","conc":false,"rit":false,"dmg":"10к10 силовое поле","cl":["Чародей","Жрец"],"ds":"Существо совершает спасбросок Телосложения: 10к10 урона (силовое поле) при провале, половина при успехе. Существо, у которого хиты опустились до 0, обращается в стихию и может быть возвращено только «Истинным воскрешением» или «Желанием». На больших уровнях: +1к10 за каждый уровень ячейки выше 6-го.","save":"Телосложение","atk":false,"mech":"Распад","theme":"Рун","orig":true,"pack":"spells6.js"},{"id":"sp6-duh-vremeni","n":"Дух Времени","l":3,"sc":"Вызов","t":"1 действие","r":"27 м","c":"ВСМ","m":"Песчинка из песочных часов.","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"1к8+6 силовое поле","cl":["Волшебник","Следопыт","Друид"],"ds":"Вы призываете духа (времени) Среднего размера: КД 13 + уровень заклинания, хиты 30 + 10 за уровень выше 3-го, скорость 12 м. Мультиатака: число атак, равное половине уровня заклинания; атака заклинанием +ваш бонус, 1к8 + 3 + уровень урона (силовое поле). Иммунитет к урону «силовое поле». Действует сразу после вас. На больших уровнях: +10 хитов и +1 КД за каждый уровень ячейки выше 3-го.","save":"","atk":true,"mech":"Дух","theme":"Времени","orig":true,"pack":"spells6.js"},{"id":"sp6-kleymo-teni","n":"Клеймо Тени","l":1,"sc":"Иллюзия","t":"1 бонусное действие","r":"На себя","c":"В","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"2к6 некротика","cl":["Следопыт","Паладин","Изобретатель"],"ds":"Следующее ваше попадание атакой оружием наносит дополнительно 2к6 урона (некротика), и цель совершает спасбросок (Мудрость) — при провале она окутывается тенью: помеха на проверки Мудрости (Восприятие) и атаки по существам дальше 9 м. На больших уровнях: +1к6 за каждый уровень ячейки выше 1-го.","save":"Мудрость","atk":false,"mech":"Клеймо","theme":"Тени","orig":true,"pack":"spells6.js"},{"id":"sp6-avatar-krovi","n":"Аватар Крови","l":6,"sc":"Преобразование","t":"1 бонусное действие","r":"На себя","c":"ВС","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"4к8 некротика","cl":["Чародей","Колдун"],"ds":"Вы становитесь аватаром стихии: иммунитет к урону «некротика», полёт 18 м, 30 временных хитов. Бонусным действием в каждый ход вы метаете снаряд (дальнобойная атака заклинанием, 36 м) на 4к8 урона (некротика). На больших уровнях: +10 временных хитов за каждый уровень ячейки выше 6-го.","save":"","atk":true,"mech":"Аватар","theme":"Крови","orig":true,"pack":"spells6.js"},{"id":"sp6-aura-molniy","n":"Аура Молний","l":3,"sc":"Ограждение","t":"1 действие","r":"На себя (3 м)","c":"В","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"2к6 электричество","cl":["Друид","Паладин","Бард"],"ds":"Вас окружает аура радиусом 3 м. Союзники в ней имеют сопротивление урону «электричество» и преимущество на спасброски от эффектов, из-за которых цель не может совершать реакции до начала своего следующего хода. Враг, начинающий ход в ауре, совершает спасбросок (Ловкость) или получает 2к6 урона (электричество). На больших уровнях: +1к6 за каждый уровень ячейки выше 3-го.","save":"Ловкость","atk":false,"mech":"Аура","theme":"Молний","orig":true,"pack":"spells6.js"},{"id":"sp6-golos-groma","n":"Голос Грома","l":1,"sc":"Очарование","t":"1 действие","r":"На себя","c":"В","m":"","d":"10 минут","conc":false,"rit":false,"dmg":"—","cl":["Чародей","Бард","Жрец"],"ds":"Ваш голос наполняется силой стихии (грома). Вы совершаете с преимуществом проверки Харизмы против существ, которые вас слышат; одно из них по вашему выбору совершает спасбросок Мудрости — при провале оно не может солгать вам до конца действия заклинания. По окончании существо знает, что на него влияли. На больших уровнях: +1 существо, которое не может лгать за каждый уровень ячейки выше 1-го.","save":"","atk":false,"mech":"Голос","theme":"Грома","orig":true,"pack":"spells6.js"},{"id":"sp6-carstvo-ineya","n":"Царство Инея","l":7,"sc":"Вызов","t":"1 минута","r":"Касание","c":"ВСМ","m":"Кристалл льда.","d":"1 день","conc":false,"rit":false,"dmg":"—","cl":["Друид","Волшебник"],"ds":"Вы и до 8 существ переноситесь в полуплан стихии (инея) площадью 150 м², где вы задаёте погоду, свет и простой рельеф. Несогласное существо может избежать переноса спасброском Харизмы. По окончании все возвращаются туда, откуда ушли. Ячейкой 9 уровня — постоянно, с единственным входом.","save":"Телосложение","atk":false,"mech":"Царство","theme":"Инея","orig":true,"pack":"spells6.js"},{"id":"sp6-perenos-plameni","n":"Перенос Пламени","l":3,"sc":"Вызов","t":"1 действие","r":"Касание","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"—","cl":["Изобретатель","Колдун","Волшебник"],"ds":"Вы и до шести согласных существ, держащихся за руки, перемещаетесь сквозь пламя на расстояние до 150 м в видимое или известное вам место. На больших уровнях: +150 м за каждый уровень ячейки выше 3-го.","save":"","atk":false,"mech":"Перенос","theme":"Пламени","orig":true,"pack":"spells6.js"},{"id":"sp6-shag-kostey","n":"Шаг Костей","l":1,"sc":"Вызов","t":"1 бонусное действие","r":"На себя","c":"В","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"1к6 колющий","cl":["Колдун","Жрец","Волшебник"],"ds":"Вы телепортируетесь на 9 м в видимое свободное место. Каждое существо в 1,5 м от точки отправления совершает спасбросок (Телосложение) или получает 1к6 урона (колющий). На больших уровнях: +3 м дистанции и +1к6 за каждый уровень ячейки выше 1-го.","save":"Телосложение","atk":false,"mech":"Шаг","theme":"Костей","orig":true,"pack":"spells6.js"},{"id":"sp6-vlast-pustoty","n":"Власть Пустоты","l":8,"sc":"Вызов","t":"1 действие","r":"На себя (1,5 км)","c":"ВС","m":"","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"6к10 силовое поле","cl":["Чародей","Колдун"],"ds":"Вы повелеваете стихией (пустоты) в радиусе 1,5 км: создаёте, гасите, перемещаете и формируете её проявления. Действием вы обрушиваете её на существо в 36 м: спасбросок (Харизма), 6к10 урона (силовое поле) при провале и цель не может телепортироваться и перемещаться между планами до конца её следующего хода, половина при успехе.","save":"Харизма","atk":false,"mech":"Власть","theme":"Пустоты","orig":true,"pack":"spells6.js"},{"id":"sp6-burya-zvezd","n":"Буря Звёзд","l":4,"sc":"Прорицание","t":"1 действие","r":"90 м","c":"ВСМ","m":"Щепоть звёздной пыли.","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"3к6 излучение","cl":["Бард","Жрец","Чародей"],"ds":"Буря (звёзд) в цилиндре радиусом 6 м и высотой 12 м: местность труднопроходимая. Существо, начинающее ход в буре или впервые входящее в неё за ход, совершает спасбросок (Мудрость): 3к6 урона (излучение) при провале, половина при успехе. На больших уровнях: +1к6 за каждый уровень ячейки выше 4-го.","save":"Мудрость","atk":false,"mech":"Буря","theme":"Звёзд","orig":true,"pack":"spells6.js"},{"id":"sp6-sfera-razuma","n":"Сфера Разума","l":2,"sc":"Очарование","t":"1 действие","r":"18 м","c":"ВСМ","m":"Кусочек мозгового коралла.","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"2к6 психический","cl":["Чародей","Колдун","Бард"],"ds":"Сфера (разума) диаметром 1,5 м появляется в пределах дистанции. Существо, оканчивающее ход в 1,5 м от неё, совершает спасбросок (Интеллект): 2к6 урона (психический) при провале, половина при успехе. Бонусным действием сфера перемещается на 9 м; если она врезается в существо, оно совершает спасбросок, и сфера останавливается. На больших уровнях: +1к6 за каждый уровень ячейки выше 2-го.","save":"Интеллект","atk":false,"mech":"Сфера","theme":"Разума","orig":true,"pack":"spells6.js"},{"id":"sp6-apokalipsis-yada","n":"Апокалипсис Яда","l":9,"sc":"Преобразование","t":"1 действие","r":"1,5 км","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"14к6+14к6 яд","cl":["Колдун","Друид"],"ds":"Вы выбираете до четырёх точек; от каждой расходится сфера радиусом 12 м. Существо в одной или нескольких сферах совершает один спасбросок (Телосложение): 14к6 урона (яд) плюс 14к6 силовым полем при провале (и цель отравлена до конца своего следующего хода), половина при успехе. Предметы и строения в области получают двойной урон.","save":"Телосложение","atk":false,"mech":"Апокалипсис","theme":"Яда","orig":true,"pack":"spells6.js"},{"id":"sp6-vrata-voln","n":"Врата Волн","l":4,"sc":"Ограждение","t":"1 действие","r":"18 м","c":"ВСМ","m":"Морская ракушка.","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"4к10 дробящий","cl":["Чародей","Жрец","Друид"],"ds":"Существо совершает спасбросок Харизмы или проваливается в карман-измерение (волн). Там оно недееспособно. Когда заклинание оканчивается, цель возвращается и получает 4к10 урона (дробящий). Если концентрация продержалась полную минуту, урон удваивается. На больших уровнях: +1 цель за каждый уровень ячейки выше 4-го.","save":"Харизма","atk":false,"mech":"Врата","theme":"Волн","orig":true,"pack":"spells6.js"},{"id":"sp6-zavesa-vetra","n":"Завеса Ветра","l":2,"sc":"Воплощение","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Концентрация, до 10 минут","conc":true,"rit":false,"dmg":"—","cl":["Следопыт","Чародей","Друид"],"ds":"Куб с ребром 6 м заполняется завесой (ветра): местность труднопроходимая и слабо заслонённая. Существо, впервые за ход входящее туда, совершает спасбросок (Сила) — при провале оно отталкивается на 4,5 м в выбранном вами направлении. На больших уровнях: +3 м к ребру куба за каждый уровень ячейки выше 2-го.","save":"Сила","atk":false,"mech":"Завеса","theme":"Ветра","orig":true,"pack":"spells6.js"},{"id":"sp6-kasanie-kamnya","n":"Касание Камня","l":0,"sc":"Преобразование","t":"1 действие","r":"Касание","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"1к8 дробящий","cl":["Изобретатель","Друид","Волшебник"],"ds":"Рукопашная атака заклинанием: при попадании 1к8 урона (дробящий), и цель сбивается с ног, если она Большая или меньше. Урон увеличивается на одну кость на 5, 11 и 17 уровнях.","save":"","atk":true,"mech":"Касание","theme":"Камня","orig":true,"pack":"spells6.js"},{"id":"sp6-tropa-duhov","n":"Тропа Духов","l":4,"sc":"Преобразование","t":"10 минут","r":"Касание","c":"ВСМ","m":"Благовония.","d":"8 часов","conc":false,"rit":true,"dmg":"—","cl":["Бард","Колдун","Жрец"],"ds":"До 8 согласных существ отправляются в путь с караваном духов: призрачные кони везут группу со скоростью 18 м. На время действия скорость путешествия группы удваивается, а случайные столкновения в пути случаются вдвое реже.","save":"","atk":false,"mech":"Тропа","theme":"Духов","orig":true,"pack":"spells6.js"},{"id":"sp6-morok-mirazhey","n":"Морок Миражей","l":2,"sc":"Очарование","t":"1 действие","r":"27 м","c":"ВС","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"—","cl":["Бард","Колдун","Волшебник"],"ds":"Существо совершает спасбросок Мудрости. При провале в начале каждого своего хода оно бросает к6: на 1–2 оно атакует ближайшее существо (кроме себя) и больше ничего не делает. В конце хода оно повторяет спасбросок. При каждом провале повторного спасброска цель также видит ложные образы: помеха на следующий бросок атаки до конца её следующего хода. На больших уровнях: +1 цель за каждый уровень ячейки выше 2-го.","save":"Мудрость","atk":false,"mech":"Морок","theme":"Миражей","orig":true,"pack":"spells6.js"},{"id":"sp6-otmetina-sveta","n":"Отметина Света","l":0,"sc":"Воплощение","t":"1 бонусное действие","r":"18 м","c":"С","m":"","d":"1 раунд","conc":false,"rit":false,"dmg":"1к4 излучение","cl":["Паладин","Следопыт","Изобретатель"],"ds":"Вы отмечаете существо знаком (света). Первое попадание по нему атакой оружием (вашей или союзника) до конца вашего следующего хода наносит дополнительно 1к4 урона (излучение). Нельзя накладывать на одно существо чаще раза в раунд. Кость урона растёт до к6, к8 и к10 на 5, 11 и 17 уровнях.","save":"","atk":false,"mech":"Отметина","theme":"Света","orig":true,"pack":"spells6.js"},{"id":"sp6-kara-shipov","n":"Кара Шипов","l":5,"sc":"Преобразование","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"8к8 колющий","cl":["Изобретатель","Друид","Чародей"],"ds":"Одно существо совершает спасбросок (Сила): 8к8 урона (колющий) при провале (и цель опутывается колючими лозами: скорость 0 до конца её следующего хода), половина при успехе. Если урон опускает хиты до 0, цель распадается, становясь прахом стихии. На больших уровнях: +1к8 за каждый уровень ячейки выше 5-го.","save":"Сила","atk":false,"mech":"Кара","theme":"Шипов","orig":true,"pack":"spells6.js"},{"id":"sp6-strazh-run","n":"Страж Рун","l":2,"sc":"Вызов","t":"1 действие","r":"9 м","c":"ВСМ","m":"Резец и кусочек кости.","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"1к8 силовое поле","cl":["Жрец","Волшебник","Друид"],"ds":"Вы призываете крошечного духа (рун): КД 14, хиты 10, полёт 9 м, действует в ваш ход. Он может совершать действие Помощь или атаковать (атака заклинанием, 1,5 м, 1к8 урона (силовое поле)). Реакцией дух бьёт существо, атакующее вас в 1,5 м от него. На больших уровнях: +5 хитов и +1к8 к урону за каждый уровень ячейки выше 2-го.","save":"","atk":true,"mech":"Страж","theme":"Рун","orig":true,"pack":"spells6.js"},{"id":"sp6-obereg-vremeni","n":"Оберег Времени","l":0,"sc":"Преобразование","t":"1 реакция (когда вы получаете урон)","r":"На себя","c":"С","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"—","cl":["Изобретатель","Волшебник","Паладин"],"ds":"Вы уменьшаете полученный урон на 1к6 + модификатор заклинательной характеристики. Если урон был типа «силовое поле», уменьшение удваивается. Кость растёт до 2к6, 3к6 и 4к6 на 5, 11 и 17 уровнях.","save":"","atk":false,"mech":"Оберег","theme":"Времени","orig":true,"pack":"spells6.js"},{"id":"sp6-svyatilische-teni","n":"Святилище Тени","l":5,"sc":"Ограждение","t":"10 минут","r":"Касание","c":"ВСМ","m":"Клочок чёрной ткани.","d":"24 часа","conc":false,"rit":false,"dmg":"—","cl":["Паладин","Изобретатель","Волшебник"],"ds":"Область радиусом 15 м становится святилищем стихии. Союзники в ней получают +1 к КД и спасброскам; враги, входящие в область, совершают спасбросок (Мудрость) — при провале они окутывается тенью: помеха на проверки Мудрости (Восприятие) и атаки по существам дальше 9 м и у них помеха на атаки по союзникам до конца хода. Ячейкой 7+ уровня длится 7 дней, 9 уровня — постоянно.","save":"Мудрость","atk":false,"mech":"Святилище","theme":"Тени","orig":true,"pack":"spells6.js"},{"id":"sp6-vzryv-krovi","n":"Взрыв Крови","l":3,"sc":"Некромантия","t":"1 действие","r":"45 м","c":"ВСМ","m":"Капля вашей крови.","d":"Мгновенная","conc":false,"rit":false,"dmg":"6к6 некротика","cl":["Чародей","Колдун","Жрец"],"ds":"Сфера радиусом 6 м: каждое существо совершает спасбросок (Телосложение), получая 6к6 урона (некротика) при провале (и цель не может восстанавливать хиты до конца своего следующего хода) или половину при успехе. На больших уровнях: +1к6 за каждый уровень ячейки выше 3-го.","save":"Телосложение","atk":false,"mech":"Взрыв","theme":"Крови","orig":true,"pack":"spells6.js"},{"id":"sp6-volna-molniy","n":"Волна Молний","l":1,"sc":"Воплощение","t":"1 действие","r":"На себя (конус 4,5 м)","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"2к6 электричество","cl":["Чародей","Изобретатель","Друид"],"ds":"Существа в конусе совершают спасбросок (Ловкость): при провале 2к6 урона (электричество) и цель не может совершать реакции до начала своего следующего хода; при успехе — половина урона без дополнительного эффекта. На больших уровнях: +1к6 за каждый уровень ячейки выше 1-го.","save":"Ловкость","atk":false,"mech":"Волна","theme":"Молний","orig":true,"pack":"spells6.js"},{"id":"sp6-svyaz-groma","n":"Связь Грома","l":5,"sc":"Прорицание","t":"10 минут","r":"Неограниченная","c":"ВСМ","m":"Маленький колокольчик.","d":"Концентрация, до 10 минут","conc":true,"rit":true,"dmg":"—","cl":["Бард","Жрец","Друид"],"ds":"Вы вопрошаете эхо этого места (оно повторяет слова, звучавшие здесь за последние сутки), но в любом месте плана, где бывали. Вы видите и слышите место, как если бы находились там, и можете говорить с присутствующими.","save":"","atk":false,"mech":"Связь","theme":"Грома","orig":true,"pack":"spells6.js"},{"id":"sp6-kokon-ineya","n":"Кокон Инея","l":3,"sc":"Ограждение","t":"1 действие","r":"18 м","c":"ВС","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"—","cl":["Чародей","Друид","Следопыт"],"ds":"Кокон (инея) окружает существо. Согласное существо получает полное укрытие и 2к10 временных хитов. Несогласное совершает спасбросок (Телосложение) — при провале оно опутано, имеет полное укрытие и не может колдовать заклинания с соматическим компонентом; в конце каждого хода повторяет спасбросок. На больших уровнях: +1 цель за каждый уровень ячейки выше 3-го.","save":"Телосложение","atk":false,"mech":"Кокон","theme":"Инея","orig":true,"pack":"spells6.js"},{"id":"sp6-pokrov-plameni","n":"Покров Пламени","l":1,"sc":"Ограждение","t":"1 действие","r":"На себя","c":"ВСМ","m":"Щепоть серы.","d":"1 час","conc":false,"rit":false,"dmg":"5 огонь","cl":["Изобретатель","Паладин","Волшебник"],"ds":"Вы получаете 5 временных хитов. Пока они есть, существо, попавшее по вам рукопашной атакой, получает 5 урона (огонь); у вас сопротивление урону «огонь». На больших уровнях: +5 временных хитов и +5 ответного урона за каждый уровень ячейки выше 1-го.","save":"","atk":false,"mech":"Покров","theme":"Пламени","orig":true,"pack":"spells6.js"},{"id":"sp6-raspad-kostey","n":"Распад Костей","l":6,"sc":"Некромантия","t":"1 действие","r":"18 м","c":"ВСМ","m":"Фаланга пальца.","d":"Мгновенная","conc":false,"rit":false,"dmg":"10к10 колющий","cl":["Колдун","Чародей"],"ds":"Существо совершает спасбросок Телосложения: 10к10 урона (колющий) при провале, половина при успехе. Существо, у которого хиты опустились до 0, обращается в стихию и может быть возвращено только «Истинным воскрешением» или «Желанием». На больших уровнях: +1к10 за каждый уровень ячейки выше 6-го.","save":"Телосложение","atk":false,"mech":"Распад","theme":"Костей","orig":true,"pack":"spells6.js"},{"id":"sp6-duh-pustoty","n":"Дух Пустоты","l":3,"sc":"Вызов","t":"1 действие","r":"27 м","c":"ВСМ","m":"Чёрная жемчужина.","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"1к8+6 силовое поле","cl":["Колдун","Волшебник","Следопыт"],"ds":"Вы призываете духа (пустоты) Среднего размера: КД 13 + уровень заклинания, хиты 30 + 10 за уровень выше 3-го, скорость 12 м. Мультиатака: число атак, равное половине уровня заклинания; атака заклинанием +ваш бонус, 1к8 + 3 + уровень урона (силовое поле). Иммунитет к урону «силовое поле». Действует сразу после вас. На больших уровнях: +10 хитов и +1 КД за каждый уровень ячейки выше 3-го.","save":"","atk":true,"mech":"Дух","theme":"Пустоты","orig":true,"pack":"spells6.js"},{"id":"sp6-kleymo-zvezd","n":"Клеймо Звёзд","l":1,"sc":"Прорицание","t":"1 бонусное действие","r":"На себя","c":"В","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"2к6 излучение","cl":["Следопыт","Паладин","Изобретатель"],"ds":"Следующее ваше попадание атакой оружием наносит дополнительно 2к6 урона (излучение), и цель совершает спасбросок (Мудрость) — при провале она очерчивается звёздным светом: атаки по ней совершаются с преимуществом до конца её следующего хода. На больших уровнях: +1к6 за каждый уровень ячейки выше 1-го.","save":"Мудрость","atk":false,"mech":"Клеймо","theme":"Звёзд","orig":true,"pack":"spells6.js"},{"id":"sp6-avatar-razuma","n":"Аватар Разума","l":6,"sc":"Преобразование","t":"1 бонусное действие","r":"На себя","c":"ВС","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"4к8 психический","cl":["Бард","Чародей"],"ds":"Вы становитесь аватаром стихии: иммунитет к урону «психический», полёт 18 м, 30 временных хитов. Бонусным действием в каждый ход вы метаете снаряд (дальнобойная атака заклинанием, 36 м) на 4к8 урона (психический). На больших уровнях: +10 временных хитов за каждый уровень ячейки выше 6-го.","save":"","atk":true,"mech":"Аватар","theme":"Разума","orig":true,"pack":"spells6.js"},{"id":"sp6-aura-yada","n":"Аура Яда","l":3,"sc":"Ограждение","t":"1 действие","r":"На себя (3 м)","c":"В","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"2к6 яд","cl":["Следопыт","Друид","Бард"],"ds":"Вас окружает аура радиусом 3 м. Союзники в ней имеют сопротивление урону «яд» и преимущество на спасброски от эффектов, из-за которых цель отравлена до конца своего следующего хода. Враг, начинающий ход в ауре, совершает спасбросок (Телосложение) или получает 2к6 урона (яд). На больших уровнях: +1к6 за каждый уровень ячейки выше 3-го.","save":"Телосложение","atk":false,"mech":"Аура","theme":"Яда","orig":true,"pack":"spells6.js"},{"id":"sp6-golos-voln","n":"Голос Волн","l":1,"sc":"Очарование","t":"1 действие","r":"На себя","c":"В","m":"","d":"10 минут","conc":false,"rit":false,"dmg":"—","cl":["Чародей","Жрец","Бард"],"ds":"Ваш голос наполняется силой стихии (волн). Вы совершаете с преимуществом проверки Харизмы против существ, которые вас слышат; одно из них по вашему выбору совершает спасбросок Мудрости — при провале оно не может солгать вам до конца действия заклинания. По окончании существо знает, что на него влияли. На больших уровнях: +1 существо, которое не может лгать за каждый уровень ячейки выше 1-го.","save":"","atk":false,"mech":"Голос","theme":"Волн","orig":true,"pack":"spells6.js"},{"id":"sp6-carstvo-vetra","n":"Царство Ветра","l":7,"sc":"Вызов","t":"1 минута","r":"Касание","c":"ВСМ","m":"Перо.","d":"1 день","conc":false,"rit":false,"dmg":"—","cl":["Друид","Бард"],"ds":"Вы и до 8 существ переноситесь в полуплан стихии (ветра) площадью 150 м², где вы задаёте погоду, свет и простой рельеф. Несогласное существо может избежать переноса спасброском Харизмы. По окончании все возвращаются туда, откуда ушли. Ячейкой 9 уровня — постоянно, с единственным входом.","save":"Сила","atk":false,"mech":"Царство","theme":"Ветра","orig":true,"pack":"spells6.js"},{"id":"sp6-perenos-kamnya","n":"Перенос Камня","l":3,"sc":"Вызов","t":"1 действие","r":"Касание","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"—","cl":["Изобретатель","Волшебник","Друид"],"ds":"Вы и до шести согласных существ, держащихся за руки, перемещаетесь сквозь камень на расстояние до 150 м в видимое или известное вам место. На больших уровнях: +150 м за каждый уровень ячейки выше 3-го.","save":"","atk":false,"mech":"Перенос","theme":"Камня","orig":true,"pack":"spells6.js"}];const D=window.DATA=window.DATA||{};D.spells=D.spells||[];const ids=new Set(D.spells.map(s=>s.id));A.forEach(s=>{if(!ids.has(s.id))D.spells.push(s)});})();
